window.__finlexDocLoaded(229,{"id":229,"articles":[{"id":5511,"no":"问1","heading":"问：甲公司处置其唯一子公司并丧失控制权，在处置子公司当期仍应编制合并财务报表，但在处置后的下一年度及后续会计期间应以原个别财务报表还是原合并财务报表为基础进行报表编制工作？","text":"【发布日期：2026-06-18】\n答：根据《企业会计准则第33号——合并财务报表》第二条，合并财务报表是指反映母公司和其全部子公司形成的企业集团整体财务状况、经营成果和现金流量的财务报表。甲公司已处置其唯一子公司，在处置子公司当期仍应编制合并财务报表，但在处置子公司下一年度及后续会计期间无需编制合并财务报表，仅需编制个别财务报表且应以原个别财务报表为基础持续编制。为确保会计信息的可比性，在编制处置子公司下一年度财务报表时，比较期间（处置子公司年度期间）应以该期间个别财务报表数据为基础列示，对于与比较期间合并财务报表的数据差异，应在财务报表附注中披露这一事实。若甲公司以后年度因新取得子公司需编制合并财务报表，除非不切实可行，新合并财务报表应再以原合并财务报表为基础持续编制。","seq":0},{"id":5512,"no":"问2","heading":"问：甲公司在202×年报告期内处置了唯一的子公司，并且于202×年12月31日已经没有子公司，那么甲公司是否需要编制202×年年度合并财务报表？","text":"【发布日期：2022-06-21】\n答：按照《企业会计准则第33号——合并财务报表》（财会〔2014〕10号）第二条、第三条、第三十三条、第三十九条、第四十四条等相关规定，合并财务报表是指反映母公司和其全部子公司形成的企业集团整体财务状况、经营成果和现金流量的财务报表，至少应当包括合并资产负债表、合并利润表、合并现金流量表、合并所有者权益（股东权益）变动表和附注；母公司在报告期内处置子公司，应当将该子公司期初至处置日的收入、费用、利润纳入合并利润表，将该子公司期初至处置日的现金流量纳入合并现金流量表，编制合并资产负债表时不应当调整合并资产负债表的期初数。因此，本问题中的甲公司应当按照《企业会计准则第33号——合并财务报表》的有关规定，编制202×年年度合并财务报表。","seq":1}]});
